    int N, K;
    scanf("%d %d", &N, &K);

    int arr[N];
    for (int i = 0; i < N; i++) {
        scanf("%d", &arr[i]);
    }

    int freq[K + 1];
    for (int i = 0; i <= K; i++) freq[i] = 0;

    int left = 0, count = 0, minLen = INT_MAX;

