int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    int *arr = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    if (k == 0) {
        printf("0\n");
        free(arr);
        return 0;
    }

    int *count = (int*)calloc(k + 1, sizeof(int));
    int have = 0; // number of distinct values from [1..K] in window
    int min_len = n + 1;
    int left = 0;

    for (int right = 0; right < n; right++) {
        int val = arr[right];
        if (val >= 1 && val <= k) {
            count[val]++;
            if (count[val] == 1) {
                have++;
            }
        }

        // Try to shrink window from left
        while (have == k) {
            int window_len = right - left + 1;
            if (window_len < min_len) {
                min_len = window_len;
            }

            int lval = arr[left];
            left++;
            if (lval >= 1 && lval <= k) {
                count[lval]--;
                if (count[lval] == 0) {
                    have--;
                }
            }
        }
    }

    if (min_len == n + 1) {
        printf("0\n");
    } else {
        printf("%d\n", min_len);
    }

    free(arr);
    free(count);
    return 0;
