        cout << 0 << '\n';
        return 0;
    }

    vector<int> freq(K + 1, 0);
    int have = 0;
    int left = 0;
    int ans = INT_MAX;

    for (int right = 0; right < N; ++right) {
        if (a[right] >= 1 && a[right] <= K) {
            if (freq[a[right]] == 0) ++have;
            ++freq[a[right]];
        }

        while (have == K) {
            ans = min(ans, right - left + 1);

            if (a[left] >= 1 && a[left] <= K) {
                --freq[a[left]];
                if (freq[a[left]] == 0) --have;
            }
            ++left;
        }
    }

    cout << (ans == INT_MAX ? 0 : ans) << '\n';
    return 0;
}

