from collections import defaultdict

def smallest_subarray_with_all_k(arr, n, k):
    required = k
    freq = defaultdict(int)
    have = 0
    left = 0
    min_len = float('inf')

    for right in range(n):
        val = arr[right]
        if 1 <= val <= k:
            if freq[val] == 0:
                have += 1
            freq[val] += 1

        while have == required:
            min_len = min(min_len, right - left + 1)
            left_val = arr[left]
            if 1 <= left_val <= k:
                freq[left_val] -= 1
                if freq[left_val] == 0:
                    have -= 1
            left += 1

    return min_len if min_len != float('inf') else 0

